    /**
     * The response of the {@value #VIEW_PLAN_PROGRESS} view.
     *
     * <p>It serialises the timestamps as ISO 8601 UTC strings (empty when not set) and the progress
     * messages as flat lists of plain strings, so that the JSON and XML outputs are easily
     * consumable by clients.
     */
    private static class PlanProgressApiResponse extends ApiResponse {

        private final int planId;
        private final String started;
        private final String finished;
        private final ApiResponseList info;
        private final ApiResponseList warn;
        private final ApiResponseList error;

        PlanProgressApiResponse(AutomationPlan plan) {
            super(VIEW_PLAN_PROGRESS);

            this.planId = plan.getId();
            this.started = toIsoInstant(plan.getStarted());
            this.finished = toIsoInstant(plan.getFinished());
            this.info = toMessageList(ELEMENT_INFO, plan.getProgress().getInfos());
            this.warn = toMessageList(ELEMENT_WARN, plan.getProgress().getWarnings());
            this.error = toMessageList(ELEMENT_ERROR, plan.getProgress().getErrors());
        }

        private static String toIsoInstant(Date date) {
            return date == null ? "" : date.toInstant().toString();
        }

        private static ApiResponseList toMessageList(String name, List<String> messages) {
            ApiResponseList list = new ApiResponseList(name);
            messages.stream()
                    .map(msg -> new ApiResponseElement(ELEMENT_MESSAGE, msg))
                    .forEach(list::addItem);
            return list;
        }

        @Override
        public JSON toJSON() {
            JSONObject json = new JSONObject();
            json.put(PARAM_PLAN_ID, planId);
            json.put(ELEMENT_STARTED, started);
            json.put(ELEMENT_FINISHED, finished);
            json.put(ELEMENT_INFO, toJsonArray(info));
            json.put(ELEMENT_WARN, toJsonArray(warn));
            json.put(ELEMENT_ERROR, toJsonArray(error));
